import {parsePythonGraph,dependencyPath,checkApplicationFiles,applicationAssessment,applicationEvidence,graphSBOM} from './application-core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge=(s,kind='neutral')=>`<span class="badge ${kind}">${esc(s)}</span>`;
const bullets=xs=>`<ul>${xs.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
const severity=s=>badge(s,s.toLowerCase());
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function api(path,data){const r=await fetch(path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:undefined,body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(250000)});let result;try{result=await r.json();}catch{throw new Error('Start server.mjs from the v0.3 folder. The current server does not provide this API.');}if(!r.ok)throw new Error(result.error||'Request failed.');return result;}
export const demoFiles=[
 {path:'pip-inspect.json',content:JSON.stringify({version:'1',environment:{python_full_version:'3.11.0',sys_platform:'linux'},installed:[{requested:true,metadata:{name:'requests',version:'2.19.1',requires_dist:['urllib3>=1.21.1,<1.24','idna>=2.5,<2.8','chardet>=3.0.2,<3.1.0','certifi>=2017.4.17']}},{requested:false,metadata:{name:'urllib3',version:'1.23',requires_dist:['PySocks>=1.5.6; extra == "socks"']}},{requested:false,metadata:{name:'idna',version:'2.7'}}]},null,2)},
 {path:'openapi.json',content:JSON.stringify({openapi:'3.0.3',info:{title:'Illustrative upload service',version:'1.0'},servers:[{url:'http://localhost:8080'}],components:{securitySchemes:{bearerAuth:{type:'http',scheme:'bearer',bearerFormat:'JWT'}}},security:[{bearerAuth:[]}],paths:{'/upload':{post:{security:[],responses:{200:{description:'OK'}}}},'/profile':{get:{responses:{200:{description:'OK'}}}}}},null,2)},
 {path:'Dockerfile',content:'FROM python:latest\nWORKDIR /app\nCOPY . .\nUSER root\nCMD ["python", "app.py"]\n'},
 {path:'compose.json',content:JSON.stringify({services:{api:{image:'example/api:latest',privileged:true,volumes:[{type:'bind',source:'/var/run/docker.sock',target:'/var/run/docker.sock'}]}}},null,2)},
 {path:'auth.py',content:'# Deliberately unsafe demonstration fixture\nimport jwt\ndef decode_access_token(token):\n    return jwt.decode(token, options={"verify_signature": False})\n'}
];
function createApplication(files,name,demo=false){
 let graph=null;
 for(const f of files.filter(f=>/\.json$/i.test(f.path))){let doc;try{doc=JSON.parse(f.content);}catch{throw new Error('Invalid JSON: '+f.path);}if(doc.installed&&doc.version){if(graph)throw new Error('Import only one pip environment report per application.');graph=parsePythonGraph(doc);}}
 return {id:crypto.randomUUID(),name,demo,createdAt:new Date().toISOString(),inputs:files.map(f=>f.path),graph,checks:checkApplicationFiles(files),advisories:null,ai:null};
}
function aiResult(review){if(!review)return '';return `<div class="card application-panel"><h2>AI evidence review</h2><p>${esc(review.summary)}</p><p class="muted">Model confidence: ${esc(review.confidence)} · qualitative, not a probability</p><h3>Relationships to investigate</h3>${review.relationships.length?review.relationships.map(r=>`<div class="ai-evidence">${badge('Unverified hypothesis')}<p>${esc(r.hypothesis)}</p><p><strong>Validate:</strong> ${esc(r.validationNeeded)}</p><small>Evidence: ${r.evidenceIds.map(esc).join(', ')}</small></div>`).join(''):'<p>The model did not propose a cross-layer relationship.</p>'}<h3>Recommended actions</h3>${review.actions.map(a=>`<div class="ai-evidence"><p>${esc(a.action)}</p><p><strong>Verify:</strong> ${esc(a.verification)}</p><small>Evidence: ${a.evidenceIds.map(esc).join(', ')}</small></div>`).join('')}<h3>Unknowns</h3>${bullets(review.unknowns)}<details><summary>Evidence and provenance</summary><p>Model ${esc(review.metadata.model)} · ${esc(review.metadata.generatedAt)} · ${esc(review.metadata.promptVersion)}</p><code class="hash">${esc(review.metadata.contextHash)}</code>${review.evidence.map(r=>`<div class="ai-evidence"><strong>${esc(r.id)} · ${esc(r.source)}</strong><p>${esc(r.detail)}</p></div>`).join('')}</details><p class="note">${esc(review.disclaimer)}</p></div>`;}
function nodeDetails(app,id){const n=app.graph.nodes.find(x=>x.id===id);if(!n)return '';const path=dependencyPath(app.graph,n.id),outgoing=app.graph.edges.filter(e=>e.from===id),incoming=app.graph.edges.filter(e=>e.to===id),advisories=app.advisories?.packages.find(p=>p.name===id)?.advisories;return `<div class="application-node"><h3>${esc(n.name)} @ ${esc(n.version)}</h3><p>${path?`Declared path from a requested package: <strong>${path.nodes.map(esc).join(' → ')}</strong>${path.conditional?' · contains unevaluated conditions':''}`:'No path from a known requested package was found. Directness may be unknown.'}</p><p class="note">Declared paths show metadata relationships, not executed code or exploitability. Version constraints are not evaluated.</p><div class="application-columns"><div><h4>Depends on</h4>${outgoing.length?outgoing.map(e=>`<div class="graph-edge"><code>${esc(e.requirement)}</code>${badge(e.resolved?'Installed':'Not installed',e.resolved?'pass':'high')}${e.conditional?badge('Condition unevaluated'):''}</div>`).join(''):'<p>No declared dependencies in this report.</p>'}</div><div><h4>Required by</h4>${incoming.length?incoming.map(e=>`<div class="graph-edge"><button class="text-btn" data-node="${esc(e.from)}">${esc(e.from)}</button>${e.conditional?badge('Conditional'):''}</div>`).join(''):'<p>No incoming declared edges.</p>'}</div></div><h4>Matched advisories</h4>${advisories===undefined?'<p>Not checked. Run the optional OSV lookup.</p>':!advisories.length?'<p>No matching advisories returned for this package in the recorded lookup. This is not proof of safety.</p>':advisories.map(a=>`<div class="ai-evidence"><a href="https://osv.dev/vulnerability/${encodeURIComponent(a.id)}" target="_blank" rel="noopener noreferrer">${esc(a.id)}</a> ${severity(a.severity)}<p>${esc(a.summary)}</p><p>Advisory fixed-version entries: ${a.fixedVersions?.length?a.fixedVersions.map(esc).join(', '):'not available'}</p>${a.note?`<p>${esc(a.note)}</p>`:''}<small>${esc(a.severitySource||a.detailStatus)}${a.cvss?.length?' · '+a.cvss.map(v=>esc(v.vector)).join(' · '):''}</small></div>`).join('')}</div>`;}
function graphHTML(app,node){const g=app.graph;if(!g)return '<div class="card application-panel"><h2>Dependency graph not supplied</h2><p>Run <code>python -m pip inspect &gt; pip-inspect.json</code> in the project virtual environment, then include that JSON in a new application review. The app never installs or imports the packages.</p></div>';return `<div class="card application-panel"><div class="section-heading"><h2>Python dependency graph</h2><button class="btn" data-app-action="sbom">Export graph SBOM</button></div><p>${g.nodes.length} installed distributions · ${g.edges.length} declared edges · Python ${esc(g.environment.pythonVersion)}</p><div class="graph-layout"><div class="graph-nodes">${g.nodes.map(n=>{const count=app.advisories?.packages.find(p=>p.name===n.name)?.advisories.length;return `<button class="graph-node ${node===n.id?'selected':''}" data-node="${esc(n.id)}"><strong>${esc(n.name)}</strong><span>${esc(n.version)}</span><small>${n.direct?'Requested directly':n.rootKnown?'Not directly requested':'Directness unknown'}${count!==undefined?' · '+count+' advisory records':''}</small></button>`;}).join('')}</div><div>${nodeDetails(app,node||g.nodes[0]?.id)}</div></div><details><summary>Graph limitations</summary>${bullets(g.warnings)}</details></div>`;}
function assessmentHTML(app,node){const a=applicationAssessment(app),e=applicationEvidence(app);return `<div class="section-heading"><div><h2>${esc(app.name)}</h2><p class="muted" style="font-size:11px;margin-top:5px">${new Date(app.createdAt).toLocaleString()} · ${app.inputs.length} input files ${app.demo?'· Constructed demonstration fixtures':''}</p></div><button class="btn" data-app-action="export">Export full review</button></div>${app.demo?'<p class="note">Sample metadata and configurations are constructed demonstration inputs. Advisory results, when requested, come from a real OSV lookup. No live service or container was tested.</p>':''}<div class="metrics application-metrics"><div class="card metric"><div class="metric-top">Observed priority index</div><div class="metric-value"><strong>${a.score===null?'—':a.score+'/100'}</strong></div><small>${a.score===null?'No numeric score without observed findings':'Higher means greater observed priority'}</small></div><div class="card metric"><div class="metric-top">Application decision</div><div style="margin-top:16px">${badge(a.decision,a.decision==='BLOCK'?'blocked':'neutral')}</div><small>Separate from source-project policies</small></div><div class="card metric"><div class="metric-top">Evidence findings</div><div class="metric-value"><strong>${a.findings.length}</strong></div><small>Advisory records may share CVE aliases</small></div></div><details class="note"><summary>How the score is calculated</summary><p>${esc(a.formula)}</p><p>Policy: observed High/Critical findings block. Missing/partial dependency lookup, unresolved/conditional graph edges, parser warnings, or unknown advisory severity require review. Other untested layers remain explicitly outside the assessed scope.</p></details><div class="card application-panel"><h2>Assessment coverage</h2><div class="coverage-grid">${Object.entries(a.coverage).map(([key,v])=>`<div><strong>${esc(key)}</strong><span>${esc(v===true?'supplied':v===false?'missing':v??'not supplied')}</span></div>`).join('')}</div></div>${graphHTML(app,node)}<div class="card application-panel"><h2>Optional vulnerability lookup</h2><p>Check installed Python versions against OSV. This requires internet access and sends package names and versions to <strong>api.osv.dev</strong>. Source code is not sent. Results are a dated snapshot.</p><label class="consent-row"><input type="checkbox" id="osv-consent"> I agree to send this environment’s package names and versions to OSV.</label><button class="btn primary" data-app-action="osv" ${!app.graph?.nodes.length?'disabled':''}>Check known vulnerabilities</button><p class="muted">Lookup: ${esc(app.advisories?.status||'not run')}${app.advisories?.checkedAt?' · '+esc(app.advisories.checkedAt):''}</p>${app.advisories?.warnings?bullets(app.advisories.warnings):''}</div><div class="card application-panel"><h2>Findings across supplied layers</h2><div class="table-scroll"><table><thead><tr><th>Layer</th><th>Finding</th><th>Severity</th><th>Evidence location</th></tr></thead><tbody>${a.findings.map(f=>`<tr><td>${esc(f.kind)}</td><td><strong>${esc(f.title)}</strong><p class="application-why">${esc(f.why)}</p></td><td>${severity(f.severity)}</td><td>${esc(f.path)}${f.location?'<br>'+esc(f.location):''}</td></tr>`).join('')}</tbody></table>${!a.findings.length?'<p>No supported patterns or matched advisories currently recorded. Review coverage before drawing a conclusion.</p>':''}</div></div><div class="card application-panel"><h2>AI application analyst</h2><p>The local model reviews the evidence below and proposes relationships to investigate. It does not determine the score or prove an exploit chain. ${e.includedFindings} of ${e.totalFindings} findings are included, ordered by severity.</p><details><summary>Preview AI evidence</summary>${e.records.map(r=>`<div class="ai-evidence"><strong>${esc(r.id)} · ${esc(r.source)}</strong><p>${esc(r.detail)}</p></div>`).join('')}</details><div class="ai-action-row"><button class="btn" data-app-action="connect">Check Ollama</button><select id="app-ai-model" class="small-select" aria-label="Application review model" disabled><option>Connect first</option></select><button class="btn primary" data-app-action="ai" disabled>Review application with AI</button></div><p class="note">Only local Ollama models are supported. A 7B model may reason better if your PC has enough memory; all model output still needs review.</p></div>${aiResult(app.ai)}<details class="note"><summary>Scope and remaining unknowns</summary>${bullets(a.limitations)}</details>`;}
export function mountApplication(root,{state,persist,log}){
 state.applicationReviews ||= [];
 let selectedId=state.applicationReviews[0]?.id,node=null,busy=false,status='';
 const current=()=>state.applicationReviews.find(x=>x.id===selectedId);
 function draw(){if(!root.isConnected)return;const app=current();root.innerHTML=`<div class="page-heading"><div><div class="eyebrow">EVIDENCE ACROSS YOUR APPLICATION</div><h1>Application review</h1><p>Python dependencies, source, API declarations, authentication patterns, and container configuration.</p></div></div><div class="card application-panel"><h2>Collect evidence from one application</h2><p>Upload a pip inspect JSON report, OpenAPI 3.x JSON, Dockerfile, normalized Compose JSON, and/or supported source files. Use <code>docker compose config --format json &gt; compose.json</code> for Compose. This performs static checks, not live API or container testing.</p><form id="application-form"><label class="field">Application name<input id="application-name" required maxlength="80" placeholder="e.g. payments-service"></label><label class="field">Evidence files · up to 5 MB each, 20 MB total<input id="application-files" type="file" multiple required></label><div class="ai-action-row"><button class="btn primary" type="submit" ${busy?'disabled':''}>Build application review</button><button type="button" class="btn" data-app-action="demo" ${busy?'disabled':''}>Load demonstration</button></div></form></div><div class="application-status" role="status" aria-live="polite">${esc(status)}</div>${state.applicationReviews.length?`<label class="field">Saved application reviews<select id="application-select">${state.applicationReviews.map(a=>`<option value="${a.id}" ${a.id===selectedId?'selected':''}>${esc(a.name)}${a.demo?' (sample)':''}</option>`).join('')}</select></label>`:''}${app?assessmentHTML(app,node):'<p class="note">Start with the demonstration, or import your own evidence. Application reviews have their own exports and are stored in your workspace backup.</p>'}`;if(busy)root.querySelectorAll('button,input,select').forEach(x=>x.disabled=true);}
 function message(text){status=text;const el=root.querySelector('.application-status');if(el)el.textContent=text;}
 root.addEventListener('submit',async event=>{if(event.target.id!=='application-form')return;event.preventDefault();if(busy)return;const name=root.querySelector('#application-name').value.trim(),files=[...root.querySelector('#application-files').files];if(!name||!files.length){message('Provide a name and at least one input file.');return;}if(files.length>50||files.some(f=>f.size>5000000)||files.reduce((n,f)=>n+f.size,0)>20000000){message('Limit: 50 files, 5 MB per file, and 20 MB total.');return;}busy=true;try{const source=await Promise.all(files.map(async f=>({path:f.name,content:await f.text()})));const app=createApplication(source,name);state.applicationReviews.unshift(app);selectedId=app.id;node=null;persist();log('Application review created',name+' · '+files.length+' evidence files');status='Evidence parsed. Check coverage, then optionally query OSV and request AI review.';}catch(error){status=error.message;}finally{busy=false;draw();}});
 root.addEventListener('change',event=>{if(event.target.id==='application-select'){selectedId=event.target.value;node=null;status='';draw();}});
 root.addEventListener('click',async event=>{
  const nodeButton=event.target.closest('[data-node]');if(nodeButton&&!busy){node=nodeButton.dataset.node;draw();return;}
  const action=event.target.closest('[data-app-action]')?.dataset.appAction;if(!action||busy)return;const app=current();
  if(action==='demo'){const sample=createApplication(demoFiles,'Application demo',true);state.applicationReviews.unshift(sample);selectedId=sample.id;node=null;persist();log('Application demo loaded','Constructed metadata and static fixtures');status='Sample loaded. Real OSV lookup and actual local AI review are optional next steps.';draw();return;}
  if(action==='export'){download('sentinel-application-review.json',{...app,assessment:applicationAssessment(app)});log('Application evidence exported',app.name);return;}
  if(action==='sbom'){download('sentinel-python-graph.cdx.json',graphSBOM(app.graph,app.name));log('Python graph SBOM exported',app.name);return;}
  if(action==='connect'){
   const button=event.target.closest('button');button.disabled=true;message('Checking local Ollama…');try{const data=await api('/api/ai/status');if(!data.models.length)throw new Error('No local model installed. Run ollama pull qwen2.5-coder:3b.');const select=root.querySelector('#app-ai-model');select.innerHTML=data.models.map(m=>`<option value="${esc(m.name)}">${esc(m.name)}</option>`).join('');if(data.models.some(m=>m.name==='qwen2.5-coder:3b'))select.value='qwen2.5-coder:3b';select.disabled=false;root.querySelector('[data-app-action="ai"]').disabled=false;message('Ollama connected. Review the evidence preview, then generate an analysis.');}catch(e){message(e.message);}finally{button.disabled=false;}return;
  }
  if(action==='osv'){
   if(!root.querySelector('#osv-consent').checked){message('Check the consent box before sending package metadata to OSV.');return;}
   busy=true;status='Querying OSV for exact installed Python versions. This may take a minute…';draw();
   try{app.advisories=await api('/api/dependencies/check',{consent:true,packages:app.graph.nodes.map(n=>({name:n.name,version:n.version}))});app.ai=null;persist();log('Dependency advisories checked',app.name+' · '+app.advisories.status);status='Lookup '+app.advisories.status+'. Review matched advisories and unknowns.';}catch(e){app.advisories={...app.advisories,status:'failed',packages:app.advisories?.packages||[],checkedAt:app.advisories?.checkedAt||null,lastAttemptAt:new Date().toISOString(),warnings:[e.message,'Any prior advisory results are retained as a stale snapshot; this refresh did not verify their current status.']};app.ai=null;persist();status=e.message;log('Dependency lookup failed',app.name+' · results unknown');}finally{busy=false;draw();}return;
  }
  if(action==='ai'){
   const model=root.querySelector('#app-ai-model').value,evidence=applicationEvidence(app);busy=true;status='Running local AI analysis of the evidence… First use may take several minutes.';draw();
   try{const result=await api('/api/ai/application',{model,records:evidence.records});app.ai=result;persist();log('AI application review completed',app.name+' · '+result.metadata.model);status='Review saved. Relationships are hypotheses, not confirmed attack paths.';}catch(e){status=e.name==='TimeoutError'?'Model timed out. Try a smaller model after the current request finishes.':e.message;log('AI application review failed',app.name+' · no new review saved');}finally{busy=false;draw();}
  }
 });
 draw();
}
